import{_ as e,o as r,c as o,a5 as a}from"./chunks/framework.C1a7WKBV.js";const g=JSON.parse('{"title":"AI 编程工具怎么选","description":"Claude Code、Codex、Cursor 的定位差异与场景化选型建议。","frontmatter":{"title":"AI 编程工具怎么选","description":"Claude Code、Codex、Cursor 的定位差异与场景化选型建议。"},"headers":[],"relativePath":"tools/coding-tools.md","filePath":"tools/coding-tools.md","lastUpdated":1788838685000}'),d={name:"tools/coding-tools.md"};function l(n,t,i,s,h,c){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="ai-编程工具怎么选" tabindex="-1">AI 编程工具怎么选 <a class="header-anchor" href="#ai-编程工具怎么选" aria-label="Permalink to &quot;AI 编程工具怎么选&quot;">​</a></h1><p>AI 编程工具大体分三种形态：<strong>终端 Agent</strong>、<strong>桌面 IDE</strong> 和<strong>云端生成器</strong>。形态决定工作方式，比&quot;哪个更强&quot;更重要。这一篇帮你按自己的场景对号入座。（编程之外的全品类工具——聊天、图像、视频、办公 Agent 等，见《<a href="/tools/overview">AI 工具全景图</a>》。）</p><h2 id="_1-三种形态-三种工作方式" tabindex="-1">1. 三种形态，三种工作方式 <a class="header-anchor" href="#_1-三种形态-三种工作方式" aria-label="Permalink to &quot;1. 三种形态，三种工作方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th>代表</th><th>工作方式</th><th>适合谁</th></tr></thead><tbody><tr><td>终端 Agent</td><td><a href="https://claude.com/product/claude-code" target="_blank" rel="noreferrer">Claude Code</a>、<a href="https://github.com/openai/codex" target="_blank" rel="noreferrer">Codex CLI</a></td><td>你在终端描述任务，Agent 自主读代码、改文件、跑命令，多步完成</td><td>日常写代码、维护真实项目</td></tr><tr><td>桌面 IDE</td><td><a href="https://cursor.com" target="_blank" rel="noreferrer">Cursor</a>、Codex 桌面版</td><td>在图形编辑器里边写边改，AI 建议穿插在编辑流程中</td><td>喜欢图形界面、想保留完全控制感</td></tr><tr><td>云端生成器</td><td><a href="https://v0.dev" target="_blank" rel="noreferrer">v0</a>、<a href="https://bolt.new" target="_blank" rel="noreferrer">Bolt</a>、ChatGPT Canvas</td><td>在网页里描述需求，直接生成可预览的小应用</td><td>快速原型、非程序员做小工具</td></tr></tbody></table><p>三种形态不互斥：很多开发者用终端 Agent 处理主力项目，用云端生成器做小实验。</p><h2 id="_2-主力工具逐个看" tabindex="-1">2. 主力工具逐个看 <a class="header-anchor" href="#_2-主力工具逐个看" aria-label="Permalink to &quot;2. 主力工具逐个看&quot;">​</a></h2><h3 id="_2-1-claude-code" tabindex="-1">2.1 <a href="https://claude.com/product/claude-code" target="_blank" rel="noreferrer">Claude Code</a> <a class="header-anchor" href="#_2-1-claude-code" aria-label="Permalink to &quot;2.1 [Claude Code](https://claude.com/product/claude-code)&quot;">​</a></h3><p>Anthropic 的终端 Agent，也是目前 Agent 能力的标杆。</p><ul><li><strong>强项</strong>：长任务自主性好，读整个代码库的能力强，支持 MCP 扩展工具。</li><li><strong>形态</strong>：终端命令行，可脚本化、可接入 CI，也提供 VS Code 插件。</li><li><strong>适合</strong>：有终端使用习惯的开发者，接手陌生代码库，大范围重构。</li><li>安装教程：<a href="/clients/claude-code">Claude Code 全平台安装</a>。</li></ul><h3 id="_2-2-codex-cli-与-codex-桌面版" tabindex="-1">2.2 <a href="https://github.com/openai/codex" target="_blank" rel="noreferrer">Codex CLI</a> 与 Codex 桌面版 <a class="header-anchor" href="#_2-2-codex-cli-与-codex-桌面版" aria-label="Permalink to &quot;2.2 [Codex CLI](https://github.com/openai/codex) 与 Codex 桌面版&quot;">​</a></h3><p>OpenAI 的编程 Agent，CLI 与桌面双形态。</p><ul><li><strong>强项</strong>：与 ChatGPT 生态衔接，沙箱执行环境安全，桌面版对新手友好。</li><li><strong>适合</strong>：ChatGPT 付费用户，想要&quot;开箱即用&quot;桌面体验的人。</li><li>安装教程：<a href="/clients/codex-cli">Codex CLI</a>、<a href="/clients/codex-desktop">Codex 桌面版</a>。</li></ul><h3 id="_2-3-cursor" tabindex="-1">2.3 <a href="https://cursor.com" target="_blank" rel="noreferrer">Cursor</a> <a class="header-anchor" href="#_2-3-cursor" aria-label="Permalink to &quot;2.3 [Cursor](https://cursor.com)&quot;">​</a></h3><p>基于 VS Code 的 AI IDE，图形界面派的主力选择。</p><ul><li><strong>强项</strong>：编辑体验流畅，Tab 补全质量高，多文件编辑可视化、逐条确认。</li><li><strong>适合</strong>：从 VS Code 迁移过来的开发者，喜欢&quot;看着 AI 改每一处&quot;的节奏。</li><li>教程：<a href="/clients/cursor">Cursor 使用第三方 AI 接口</a>。</li></ul><h3 id="_2-4-cc-switch" tabindex="-1">2.4 <a href="https://github.com/farion1231/cc-switch" target="_blank" rel="noreferrer">CC Switch</a> <a class="header-anchor" href="#_2-4-cc-switch" aria-label="Permalink to &quot;2.4 [CC Switch](https://github.com/farion1231/cc-switch)&quot;">​</a></h3><p>严格说不是编程工具，而是<strong>供应商切换器</strong>：在多个 API 供应商（包括 STJAPI）之间一键切换 Claude Code / Codex 的配置。</p><ul><li><strong>适合</strong>：已经用上 Agent 工具、需要在多个供应商间管理配置和排障的人。</li><li>教程：<a href="/clients/cc-switch">CC Switch 对接 STJAPI</a>。</li></ul><h2 id="_3-按场景推荐" tabindex="-1">3. 按场景推荐 <a class="header-anchor" href="#_3-按场景推荐" aria-label="Permalink to &quot;3. 按场景推荐&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的情况</th><th>建议起点</th></tr></thead><tbody><tr><td>资深开发者，日常维护真实项目</td><td>Claude Code 或 Codex CLI，终端 Agent 收益最大</td></tr><tr><td>用 VS Code 多年，不想换工作流</td><td><a href="https://cursor.com" target="_blank" rel="noreferrer">Cursor</a>，或 Claude Code 的 VS Code 插件</td></tr><tr><td>刚入门编程 / 非程序员</td><td>Codex 桌面版或云端生成器，图形界面降低门槛</td></tr><tr><td>接手陌生大型代码库，需要快速摸底</td><td>终端 Agent：让它先读代码库、画架构、列疑点</td></tr><tr><td>需要在多个 API 供应商间切换</td><td>任选主力工具 + CC Switch 管理配置</td></tr></tbody></table><h2 id="_4-决定收益的不是工具-是用法" tabindex="-1">4. 决定收益的不是工具，是用法 <a class="header-anchor" href="#_4-决定收益的不是工具-是用法" aria-label="Permalink to &quot;4. 决定收益的不是工具，是用法&quot;">​</a></h2><ol><li><strong>任务粒度给对</strong>：Agent 工具适合&quot;完成 X 这个目标&quot;，IDE 补全适合&quot;改这一段&quot;。拿 Agent 干碎片小事，或拿补全干大重构，都会失望。</li><li><strong>先让它读，再让它改</strong>：陌生项目先让 Agent 分析现状、提出方案，确认后再动手，成功率显著更高。</li><li><strong>配置稳定是体验的一半</strong>：Agent 工具重度依赖 API 连接质量。接口不稳定时，任何工具都&quot;变笨&quot;。建议按《STJAPI 账户与网络设置》把接入环境理顺，再评价工具本身。</li><li><strong>每周复盘一次工作流</strong>：AI 编程工具迭代极快，定期检查&quot;哪些步骤我还在手工做，AI 能不能接手&quot;，比追逐新工具有用。</li></ol><p>选好了工具，就去《<a href="/getting-started/stjapi">接入实战</a>》板块把它跑起来；用起来之后，按《<a href="/tips/roadmap">从零到驾驭 AI：成长路径</a>》第四阶段把协作习惯养对。</p>',23)])])}const C=e(d,[["render",l]]);export{g as __pageData,C as default};
